//! Cross-repo golden-vector test for the schema 2 canonical encoder.
//!
//! The 148-byte vector below is the **frozen schema 2 wire golden from the
//! kernel repo** (`lengsuo-browser`, `native/golden_v2.inc`, generated by that
//! repo's own `tests/golden_v2/gen_golden_v2.py`). It was produced by an
//! independent implementation in another repository, *not* by this crate.
//! This test therefore pins the wire format against an outside authority: it
//! deliberately does **not** decode the bytes and re-encode them to "prove"
//! roundtrip self-consistency, because a roundtrip would pass even if both
//! ends of this crate were wrong in the same way.
//!
//! The 147-byte vector is the same dictionary under schema 1 with no policy
//! byte; it must equal the pre-existing frozen v1 golden (see
//! `tests/canonical.rs::GOLDEN_BYTES`) byte for byte, which is the regression
//! evidence that adding the schema 2 field did not move any v1 offset.

use std::collections::BTreeMap;

use lengsuo_browser_profile::{
    HardwareSpec, LocaleSpec, Platform, ProfileError, ProfileSpec, ScreenSpec,
    WebRtcIpHandlingPolicy, SCHEMA_VERSION_V1, SCHEMA_VERSION_V2,
};

/// Kernel-repo frozen schema 2 golden, 148 bytes, lowercase hex.
const GOLDEN_V2_HEX: &str = concat!(
    "4c42504631", // magic "LBPF1"
    "00000002",   // schema_version = 2
    "00000001",   // noise_version = 1
    "0005",
    "656e762d31", // environment_id "env-1"
    "0002",
    "7031",             // pool_version "p1"
    "0001020304050607", // noise_seed
    "00",               // platform Windows
    "00000780",
    "00000438",
    "18",
    "000003e8", // 1920x1080, depth 24, dpr 1000
    "0008",
    "00002000",
    "00", // cpu 8, memory 8192, touch 0
    "0005",
    "656e2d5553", // language "en-US"
    "0003",
    "555443", // timezone "UTC"
    "02",     // webrtc_ip_handling_policy = 2
    "0007",   // slot_count = 7
    "0005",
    "617564696f",
    "00000003", // audio = 3
    "0006",
    "63616e766173",
    "00000001", // canvas = 1
    "000c",
    "636c69656e745f7265637473",
    "00000005", // client_rects = 5
    "0005",
    "666f6e7473",
    "00000004", // fonts = 4
    "0003",
    "677075",
    "00000006", // gpu = 6
    "0002",
    "7561",
    "00000007", // ua = 7
    "0005",
    "776562676c",
    "00000002", // webgl = 2
);

/// The same dictionary under schema 1: identical to the v1 golden above with
/// `schema_version = 1` and no policy byte (147 bytes).
const GOLDEN_V1_HEX: &str = concat!(
    "4c42504631",
    "00000001",
    "00000001",
    "0005",
    "656e762d31",
    "0002",
    "7031",
    "0001020304050607",
    "00",
    "00000780",
    "00000438",
    "18",
    "000003e8",
    "0008",
    "00002000",
    "00",
    "0005",
    "656e2d5553",
    "0003",
    "555443",
    "0007",
    "0005",
    "617564696f",
    "00000003",
    "0006",
    "63616e766173",
    "00000001",
    "000c",
    "636c69656e745f7265637473",
    "00000005",
    "0005",
    "666f6e7473",
    "00000004",
    "0003",
    "677075",
    "00000006",
    "0002",
    "7561",
    "00000007",
    "0005",
    "776562676c",
    "00000002",
);

/// Byte offset of `schema_version` inside the goldens (right after the magic).
const SCHEMA_FIELD_OFFSET: usize = 5;

/// Byte offset of `webrtc_ip_handling_policy` inside the frozen v2 golden.
/// Derived from the frozen layout (5+4+4+2+5+2+2+8+1+4+4+1+4+2+4+1+2+5+2+3 = 65),
/// not from this crate's encoder output.
const POLICY_OFFSET: usize = 65;

fn hex_bytes(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "test helper: even hex length");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("test helper hex"))
        .collect()
}

fn golden_slots() -> BTreeMap<String, u32> {
    let mut m = BTreeMap::new();
    for (name, id) in [
        ("audio", 3u32),
        ("canvas", 1),
        ("client_rects", 5),
        ("fonts", 4),
        ("gpu", 6),
        ("ua", 7),
        ("webgl", 2),
    ] {
        m.insert(name.to_string(), id);
    }
    m
}

/// The kernel-repo `FIELDS` dictionary, as this crate's public contract type.
fn golden_dict(schema: u32, policy: Option<u8>) -> ProfileSpec {
    ProfileSpec {
        schema_version: schema,
        environment_id: "env-1".to_string(),
        pool_version: "p1".to_string(),
        noise_version: 1,
        noise_seed_hex: "0001020304050607".to_string(),
        platform: Platform::Windows,
        screen: ScreenSpec {
            width: 1920,
            height: 1080,
            color_depth: 24,
            dpr_milli: 1000,
        },
        hardware: HardwareSpec {
            cpu_cores: 8,
            memory_mib: 8192,
            max_touch_points: 0,
        },
        locale: LocaleSpec {
            language: "en-US".to_string(),
            timezone: "UTC".to_string(),
        },
        webrtc_ip_handling_policy: policy.map(WebRtcIpHandlingPolicy),
        slots: golden_slots(),
    }
}

fn golden_v2() -> ProfileSpec {
    golden_dict(SCHEMA_VERSION_V2, Some(2))
}

#[test]
fn schema2_encoding_equals_the_kernel_repo_golden_byte_for_byte() {
    let spec = golden_v2();
    spec.validate()
        .expect("kernel golden dictionary must validate");
    let bytes = spec.canonical_bytes().unwrap();
    let golden = hex_bytes(GOLDEN_V2_HEX);
    assert_eq!(golden.len(), 148, "frozen golden is 148 bytes");
    assert_eq!(bytes, golden, "schema 2 wire bytes diverged from golden");
    assert_eq!(bytes.len(), 148);
    // No trailing byte: the stream ends exactly with the last slot id.
    assert_eq!(&bytes[144..], &[0x00, 0x00, 0x00, 0x02]);
    assert_eq!(bytes[POLICY_OFFSET], 2);
}

#[test]
fn v1_layout_is_unchanged_by_the_schema2_field() {
    let spec = golden_dict(SCHEMA_VERSION_V1, None);
    spec.validate().unwrap();
    let v1 = spec.canonical_bytes().unwrap();
    let golden_v1 = hex_bytes(GOLDEN_V1_HEX);
    assert_eq!(v1, golden_v1, "v1 byte layout must not drift");
    assert_eq!(v1.len(), 147);

    let v2 = hex_bytes(GOLDEN_V2_HEX);
    // The two goldens differ in exactly two places: the 4-byte schema_version
    // field (offset 5..9, value 1 vs 2) and the single policy byte at offset
    // 65. Every other position is byte-identical, which is only possible if
    // the writer places the policy byte explicitly rather than encoding v1 and
    // splicing a byte in afterwards (that would shift no field, but here the
    // fields *after* the policy also line up with the frozen golden).
    assert_eq!(
        &v1[..SCHEMA_FIELD_OFFSET],
        &v2[..SCHEMA_FIELD_OFFSET],
        "magic prefix must not drift"
    );
    assert_eq!(
        &v1[SCHEMA_FIELD_OFFSET..SCHEMA_FIELD_OFFSET + 3],
        &[0, 0, 0]
    );
    assert_eq!(v1[SCHEMA_FIELD_OFFSET + 3], 1);
    assert_eq!(v2[SCHEMA_FIELD_OFFSET + 3], 2);
    assert_eq!(
        &v1[SCHEMA_FIELD_OFFSET + 4..POLICY_OFFSET],
        &v2[SCHEMA_FIELD_OFFSET + 4..POLICY_OFFSET],
        "all fields before the policy byte are identical"
    );
    assert_eq!(&v1[POLICY_OFFSET..], &v2[POLICY_OFFSET + 1..]);

    // The v1 digest vector pinned in tests/canonical.rs must still hold, i.e.
    // adding the schema 2 field did not change any v1 identity.
    assert_eq!(
        spec.identity_digest().unwrap(),
        "4f697737e51b7179bb1bf9874322494c366e6ea55013ef4f293407c76412d80b"
    );
}

#[test]
fn schema2_with_illegal_policy_code_is_rejected() {
    for code in [4u8, 5, 100, 255] {
        let spec = golden_dict(SCHEMA_VERSION_V2, Some(code));
        let err = spec
            .validate()
            .expect_err(&format!("policy code {code} must be refused"));
        assert_eq!(err, ProfileError::WebRtcPolicyValue(code), "code {code}");
        assert!(spec.canonical_bytes().is_err(), "code {code} encoded");
        assert!(spec.identity_digest().is_err(), "code {code} digested");
    }
    // Same refusal through the JSON entry point (fail-closed, no clamping).
    let text = r#"{"schema_version":2,"environment_id":"env-1","pool_version":"p1",
        "noise_version":1,"noise_seed_hex":"0001020304050607","platform":"windows",
        "screen":{"width":1920,"height":1080,"color_depth":24,"dpr_milli":1000},
        "hardware":{"cpu_cores":8,"memory_mib":8192,"max_touch_points":0},
        "locale":{"language":"en-US","timezone":"UTC"},
        "webrtc_ip_handling_policy":4,
        "slots":{"audio":3,"canvas":1,"client_rects":5,"fonts":4,"gpu":6,"ua":7,"webgl":2}}"#;
    let parsed = ProfileSpec::from_json_str(text).unwrap();
    assert_eq!(
        parsed.validate().unwrap_err(),
        ProfileError::WebRtcPolicyValue(4)
    );
}

#[test]
fn schema2_without_policy_is_rejected_not_defaulted() {
    let spec = golden_dict(SCHEMA_VERSION_V2, None);
    assert_eq!(
        spec.validate().unwrap_err(),
        ProfileError::MissingWebRtcPolicy,
        "a v2 profile missing the policy must be refused, never defaulted"
    );
    assert!(spec.canonical_bytes().is_err());
    assert!(spec.identity_digest().is_err());

    // And through JSON: the field simply absent must not be silently treated
    // as "no policy required".
    let mut value = serde_json::to_value(golden_v2()).unwrap();
    value
        .as_object_mut()
        .unwrap()
        .remove("webrtc_ip_handling_policy");
    let parsed = ProfileSpec::from_json_str(&value.to_string()).unwrap();
    assert_eq!(parsed.schema_version, SCHEMA_VERSION_V2);
    assert_eq!(
        parsed.validate().unwrap_err(),
        ProfileError::MissingWebRtcPolicy
    );
}

#[test]
fn schema1_carrying_policy_is_refused_explicitly() {
    // Documented choice: **refuse**, do not ignore. Silently dropping the
    // value would let a v1 stream whose author believed a policy was applied
    // pass as an effective-policy profile, which is exactly the "signed as
    // usable but never enforced" gap this field is meant to close.
    let spec = golden_dict(SCHEMA_VERSION_V1, Some(2));
    assert_eq!(
        spec.validate().unwrap_err(),
        ProfileError::WebRtcPolicyInSchemaV1
    );
    assert!(spec.canonical_bytes().is_err());
    assert!(spec.identity_digest().is_err());

    let mut value = serde_json::to_value(golden_dict(SCHEMA_VERSION_V1, None)).unwrap();
    value["webrtc_ip_handling_policy"] = serde_json::json!(2);
    let parsed = ProfileSpec::from_json_str(&value.to_string()).unwrap();
    assert_eq!(parsed.schema_version, SCHEMA_VERSION_V1);
    assert_eq!(
        parsed.validate().unwrap_err(),
        ProfileError::WebRtcPolicyInSchemaV1
    );
}

#[test]
fn every_policy_code_changes_the_bytes_and_the_digest() {
    let base = golden_dict(SCHEMA_VERSION_V2, Some(0));
    base.validate().unwrap();
    let mut digests = Vec::new();
    for code in 0..4u8 {
        let spec = golden_dict(SCHEMA_VERSION_V2, Some(code));
        let bytes = spec.canonical_bytes().unwrap();
        assert_eq!(bytes.len(), 148);
        assert_eq!(bytes[POLICY_OFFSET], code);
        let mut expected = hex_bytes(GOLDEN_V2_HEX);
        expected[POLICY_OFFSET] = code;
        assert_eq!(bytes, expected, "only the policy byte may differ");
        digests.push(spec.identity_digest().unwrap());
    }
    for (i, a) in digests.iter().enumerate() {
        for (j, b) in digests.iter().enumerate() {
            if i != j {
                assert_ne!(a, b, "policy codes {i} and {j} collided in the digest");
            }
        }
    }
}

#[test]
fn schema_version_itself_reaches_the_digest_input() {
    // Same fingerprint settings, same policy value spelled in the v1 slot:
    // schema 1 refuses, so the only legal v2-vs-v1 pair differs by version.
    let v2 = golden_v2();
    let mut v1 = golden_dict(SCHEMA_VERSION_V1, None);
    v1.slots = v2.slots.clone();
    assert_ne!(
        v1.identity_digest().unwrap(),
        v2.identity_digest().unwrap(),
        "the schema version field must separate v1 and v2 identities"
    );
}
